def _canonical_json(value: Any) -> bytes:
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")


def _sha256(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def _parse_structured(result: dict[str, Any]) -> dict[str, Any]:
    if isinstance(result.get("result"), dict):
        result = result["result"]
    value = result.get("structuredContent")
    if not isinstance(value, dict):
        raise ValueError("tool result is missing structuredContent")
    if not isinstance(value.get("ok"), bool):
        raise ValueError("tool result is missing boolean ok")
    if value["ok"] and not isinstance(value.get("data"), (dict, list)):
        raise ValueError("successful tool result is missing data")
    return value


def _json_resource(result: dict[str, Any]) -> Any:
    contents = (result.get("result") or {}).get("contents")
    if not isinstance(contents, list) or not contents:
        raise ValueError("resource response has no contents")
    text = contents[0].get("text")
    if not isinstance(text, str):
        raise ValueError("resource response is not text")
    return json.loads(text)


def _text_resource(result: dict[str, Any]) -> str:
    contents = (result.get("result") or {}).get("contents")
    if not isinstance(contents, list) or not contents:
        raise ValueError("resource response has no contents")
    text = contents[0].get("text")
    if not isinstance(text, str):
        raise ValueError("resource response is not text")
    return text


def _contains_any(text: str, needles: Sequence[str]) -> bool:
    lower = text.lower()
    return any(needle in lower for needle in needles)


def _semantic_fixture() -> tuple[list[dict[str, str]], dict[str, Any]]:
    """Return a tiny deterministic panel and its protocol conformance graph.

    The vector deliberately avoids named factors and external data. It covers
    field selection, per-stock lag, guarded arithmetic, a trailing window and a
    cross-sectional rank, which are the minimum observable semantics an
    independent Alpha Graph implementation must agree on.
    """
    dates = [
        "20240102",
        "20240103",
        "20240104",
        "20240105",
        "20240108",
        "20240109",
        "20240110",
        "20240111",
        "20240112",
    ]
    closes = {
        "000001.SZ": [10.0, 11.0, 12.0, 13.0, 14.0, 15.0, 16.0, 17.0, 18.0],
        "000002.SZ": [20.0, 19.0, 18.0, 17.0, 16.0, 15.0, 14.0, 13.0, 12.0],
        "000003.SZ": [5.0, 6.0, 7.0, 8.0, 9.0, 10.0, 11.0, 12.0, 13.0],
        "000004.SZ": [30.0, 30.5, 31.0, 31.5, 32.0, 32.5, 33.0, 33.5, 34.0],
    }
    rows: list[dict[str, str]] = []
    for code, prices in closes.items():
        for index, (date, close) in enumerate(zip(dates, prices, strict=True)):
            rows.append({
                "ts_code": code,
                "trade_date": date,
                "open": str(close),
                "high": str(close * 1.01),
                "low": str(close * 0.99),
                "close": str(close),
                "vol": str(1000.0 + index),
                "amount": str((1000.0 + index) * close),
            })
    graph = {
        "version": "alpha-graph-1",
        "nodes": [
            {"id": "close", "op": "field", "field": "close"},
            {
                "id": "lag2",
                "op": "operator",
                "operator": "delay",
                "input": "close",
                "stocks": "ts_code",
                "periods": 2,
            },
            {
                "id": "ratio",
                "op": "operator",
                "operator": "safe_divide",
                "inputs": ["close", "lag2"],
            },
            {
                "id": "smoothed",
                "op": "operator",
                "operator": "ts_mean",
                "input": "ratio",
                "stocks": "ts_code",
                "window": 3,
                "min_periods": 2,
            },
            {"id": "ranked", "op": "rank", "input": "smoothed"},
        ],
        "outputs": ["smoothed", "ranked"],
    }
    return rows, graph


def _calculate_semantic_rows(
    rows: Sequence[dict[str, str]],
) -> list[dict[str, Any]]:
    """Compute the conformance vector with standard-library arithmetic only."""
    grouped: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        grouped.setdefault(str(row["ts_code"]), []).append(dict(row))
    values: dict[tuple[str, str], dict[str, Any]] = {}
    for code, stock_rows in grouped.items():
        stock_rows.sort(key=lambda row: str(row["trade_date"]))
        closes = [float(row["close"]) for row in stock_rows]
        ratios: list[float | None] = [
            None if index < 2 else closes[index] / closes[index - 2]
            for index in range(len(closes))
        ]
        for index, row in enumerate(stock_rows):
            sample = [
                value
                for value in ratios[max(0, index - 2):index + 1]
                if value is not None
            ]
            smoothed = (
                sum(sample) / len(sample)
                if len(sample) >= 2
                else None
            )
            values[(code, str(row["trade_date"]))] = {
                "ts_code": code,
                "trade_date": str(row["trade_date"]),
                "smoothed": smoothed,
                "ranked": None,
            }

    by_date: dict[str, list[dict[str, Any]]] = {}
    for value in values.values():
        by_date.setdefault(str(value["trade_date"]), []).append(value)
    for same_date in by_date.values():
        available = [
            item for item in same_date
            if item["smoothed"] is not None
        ]
        ordered = sorted(
            available,
            key=lambda item: float(item["smoothed"]),
        )
        position = 0
        while position < len(ordered):
            end = position + 1
            while (
                end < len(ordered)
                and float(ordered[end]["smoothed"])
                == float(ordered[position]["smoothed"])
            ):
                end += 1
            average_rank = ((position + 1) + end) / 2.0
            percentile = average_rank / len(ordered)
            for item in ordered[position:end]:
                item["ranked"] = percentile
            position = end
    return sorted(
        values.values(),
        key=lambda item: (str(item["ts_code"]), str(item["trade_date"])),
    )


def _compare_semantic_values(
    observed: Sequence[dict[str, str]],
    expected: Sequence[dict[str, Any]],
    *,
    tolerance: float = 1e-9,
) -> dict[str, Any]:
    observed_index = {
        (str(row.get("ts_code")), str(row.get("trade_date"))): row
        for row in observed
    }
    mismatches: list[dict[str, Any]] = []
    compared = 0
    maximum_error = 0.0
    for expected_row in expected:
        key = (str(expected_row["ts_code"]), str(expected_row["trade_date"]))
        observed_row = observed_index.get(key)
        if observed_row is None:
            mismatches.append({
                "key": list(key),
                "field": "row",
                "expected": "present",
                "observed": "missing",
            })
            continue
        for field in ("smoothed", "ranked"):
            compared += 1
            expected_value = expected_row[field]
            raw_observed = observed_row.get(field)
            if expected_value is None:
                if raw_observed not in (None, ""):
                    mismatches.append({
                        "key": list(key),
                        "field": field,
                        "expected": None,
                        "observed": raw_observed,
                    })
                continue
            try:
                observed_value = float(raw_observed)
            except (TypeError, ValueError):
                mismatches.append({
                    "key": list(key),
                    "field": field,
                    "expected": expected_value,
                    "observed": raw_observed,
                })
                continue
            if not math.isfinite(observed_value):
                mismatches.append({
                    "key": list(key),
                    "field": field,
                    "expected": expected_value,
                    "observed": raw_observed,
                })
                continue
            error = abs(observed_value - float(expected_value))
            maximum_error = max(maximum_error, error)
            if error > tolerance:
                mismatches.append({
                    "key": list(key),
                    "field": field,
                    "expected": expected_value,
                    "observed": observed_value,
                    "absoluteError": error,
                })
    return {
        "passed": not mismatches,
        "rowsExpected": len(expected),
        "rowsObserved": len(observed),
        "valuesCompared": compared,
        "tolerance": tolerance,
        "maximumAbsoluteError": maximum_error,
        "mismatchCount": len(mismatches),
        "mismatches": mismatches[:20],
    }


def _read_semantic_artifact(path: str | Path) -> list[dict[str, str]]:
    target = Path(path).expanduser().resolve()
    if target.stat().st_size > 2 * 1024 * 1024:
        raise ValueError("semantic artifact exceeds the 2 MiB safety limit")
    with target.open("r", encoding="utf-8", newline="") as handle:
        return list(csv.DictReader(handle))


def _run_semantic_vectors(
    transport: Any,
    transcript: Transcript,
    *,
    request_id: int,
    timeout: float,
) -> dict[str, Any]:
    """Execute the synthetic vector through the runtime's Alpha Graph tool."""
    rows, graph = _semantic_fixture()
    expected = _calculate_semantic_rows(rows)
    result: dict[str, Any] = {
        "format": SEMANTIC_FORMAT,
        "status": "ERROR",
        "conforming": False,
        "fixture": "alpha-graph-operator-vector/1",
        "executedSyntheticVectors": False,
        "mutatedResearchState": False,
        "uploadedLocalContent": False,
    }
    with tempfile.TemporaryDirectory(prefix="qprotocol-semantic-") as directory:
        root = Path(directory)
        panel_path = root / "panel.csv"
        graph_path = root / "graph.json"
        output_dir = root / "output"
        with panel_path.open("w", encoding="utf-8", newline="") as handle:
            writer = csv.DictWriter(handle, fieldnames=list(rows[0]))
            writer.writeheader()
            writer.writerows(rows)
        graph_path.write_text(
            json.dumps(graph, ensure_ascii=False, sort_keys=True),
            encoding="utf-8",
        )
        try:
            response = _request(
                transport,
                transcript,
                request_id,
                "tools/call",
                {
                    "name": "quant_alpha_graph",
                    "arguments": {
                        "dataPath": str(panel_path),
                        "startDate": "20240102",
                        "endDate": "20240112",
                        "specPath": str(graph_path),
                        "outputDir": str(output_dir),
                        "horizon": 1,
                        "minNames": 3,
                    },
                },
            )
            envelope = _parse_structured(response or {})
            if not envelope.get("ok"):
                raise ValueError(
                    "quant_alpha_graph returned ok=false: "
                    + str(envelope.get("error") or "<missing error>")
                )
            data = envelope.get("data")
            if not isinstance(data, dict):
                raise ValueError("quant_alpha_graph data is not an object")
            artifacts = data.get("artifacts") or {}
            values_path = artifacts.get("values") if isinstance(artifacts, dict) else None
            if not isinstance(values_path, str) or not values_path:
                raise ValueError(
                    "quant_alpha_graph did not return artifacts.values"
                )
            resolved_values = Path(values_path).expanduser().resolve()
            resolved_output = output_dir.resolve()
            if not resolved_values.is_relative_to(resolved_output):
                raise ValueError(
                    "quant_alpha_graph returned an artifact outside its "
                    "temporary conformance directory"
                )
            observed = _read_semantic_artifact(values_path)
            comparison = _compare_semantic_values(observed, expected)
            if not comparison["passed"]:
                raise ValueError(
                    "semantic vector differs: "
                    f"{comparison['mismatchCount']} mismatches; "
                    f"max error {comparison['maximumAbsoluteError']}"
                )
            engine = data.get("engine")
            if not isinstance(engine, dict) or int(engine.get("nodesEvaluated") or 0) != 5:
                raise ValueError(
                    "semantic vector did not evaluate all five graph nodes"
                )
            result.update({
                "status": "CONFORMING",
                "conforming": True,
                "executedSyntheticVectors": True,
                "comparison": comparison,
                "engine": engine,
            })
            transcript.check(
                "semantic.alpha_graph_operator_vector",
                True,
                detail=comparison,
            )
        except Exception as error:  # noqa: BLE001 - conformance evidence
            result["error"] = f"{type(error).__name__}: {error}"
            transcript.check(
                "semantic.alpha_graph_operator_vector",
                False,
                detail={"error": result["error"]},
            )
    return result


class Transcript:
    """Collect checks and bounded protocol evidence."""

    def __init__(self, *, transport: str, target: str) -> None:
        self.transport = transport
        self.target = target
        self.checks: list[dict[str, Any]] = []
        self.responses: list[dict[str, Any]] = []

    def check(
        self,
        check_id: str,
        passed: bool,
        *,
        detail: Any = None,
    ) -> bool:
        item: dict[str, Any] = {
            "id": check_id,
            "passed": bool(passed),
        }
        if detail is not None:
            item["detail"] = detail
        self.checks.append(item)
        return bool(passed)

    def record(self, response: Any) -> None:
        if isinstance(response, dict):
            self.responses.append(response)

    def attempt(
        self,
        check_id: str,
        function: Any,
        *,
        detail: Any = None,
    ) -> Any:
        try:
            value = function()
        except Exception as error:  # noqa: BLE001 - conformance evidence
            self.check(
                check_id,
                False,
                detail={
                    **(detail if isinstance(detail, dict) else {}),
                    "error": f"{type(error).__name__}: {error}",
                },
            )
            return None
        self.check(check_id, True, detail=detail)
        return value


class StdioTransport:
    def __init__(
        self,
        command: str,
        args: Sequence[str],
        *,
        cwd: str | Path | None,
        timeout: float,
    ) -> None:
        self.timeout = float(timeout)
        self.stderr = ""
        self._stdout: queue.Queue[str | None] = queue.Queue()
        self._stderr_parts: list[str] = []
        self.process = subprocess.Popen(
            [str(command), *[str(item) for item in args]],
            cwd=str(cwd) if cwd else None,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            bufsize=1,
            env={**os.environ, "NO_COLOR": "1"},
        )
        threading.Thread(target=self._read_stdout, daemon=True).start()
        threading.Thread(target=self._read_stderr, daemon=True).start()

    def _read_stdout(self) -> None:
        assert self.process.stdout is not None
        for line in self.process.stdout:
            self._stdout.put(line)
        self._stdout.put(None)

    def _read_stderr(self) -> None:
        assert self.process.stderr is not None
        for line in self.process.stderr:
            self._stderr_parts.append(line)
            if sum(len(item) for item in self._stderr_parts) > 32_768:
                self._stderr_parts = ["".join(self._stderr_parts)[-16_384:]]

    def _wait_line(self) -> str:
        line = self._stdout.get(timeout=self.timeout)
        if line is None:
            self.stderr = "".join(self._stderr_parts)
            raise RuntimeError(
                "MCP process exited before returning a response"
                + (f": {self.stderr[-2000:]}" if self.stderr else "")
            )
        return line

    def request(
        self,
        payload: dict[str, Any],
        *,
        expect_response: bool = True,
    ) -> dict[str, Any] | None:
        assert self.process.stdin is not None
        self.process.stdin.write(
            json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
            + "\n"
        )
        self.process.stdin.flush()
        if not expect_response:
            return None
        request_id = payload.get("id")
        deadline = time.monotonic() + self.timeout
        while time.monotonic() < deadline:
            line = self._wait_line()
            try:
                response = json.loads(line)
            except json.JSONDecodeError:
                continue
            if response.get("id") == request_id:
                return response
        raise TimeoutError(f"MCP request timed out: {request_id}")

    def close(self) -> None:
        if self.process.stdin:
            try:
                self.process.stdin.close()
            except OSError:
                pass
        try:
            self.process.wait(timeout=3)
        except subprocess.TimeoutExpired:
            self.process.terminate()
            try:
                self.process.wait(timeout=2)
            except subprocess.TimeoutExpired:
                self.process.kill()
                self.process.wait(timeout=2)
        for stream in (self.process.stdout, self.process.stderr):
            if stream:
                try:
                    stream.close()
                except OSError:
                    pass
        self.stderr = "".join(self._stderr_parts)


class HttpTransport:
    def __init__(self, url: str, *, token: str, timeout: float) -> None:
        self.url = str(url)
        parsed = urllib.parse.urlsplit(self.url)
        if parsed.scheme not in {"http", "https"}:
            raise ValueError("HTTP MCP URL must use http or https")
        if str(parsed.hostname or "").lower() not in {
            "127.0.0.1",
            "::1",
            "localhost",
        }:
            raise ValueError(
                "Quant Research Protocol HTTP transport must bind loopback only"
            )
        self.token = str(token)
        self.timeout = float(timeout)
        self.session_id: str | None = None

    def _headers(self) -> dict[str, str]:
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream",
            "Authorization": f"Bearer {self.token}",
        }
        if self.session_id:
            headers["Mcp-Session-Id"] = self.session_id
        return headers

    @staticmethod
    def _decode_response(content_type: str, body: bytes) -> dict[str, Any]:
        text = body.decode("utf-8")
        if "text/event-stream" in content_type.lower():
            values = [
                line[5:].strip()
                for line in text.splitlines()
                if line.startswith("data:")
            ]
            for value in reversed(values):
                try:
                    parsed = json.loads(value)
                except json.JSONDecodeError:
                    continue
                if isinstance(parsed, dict):
                    return parsed
            raise ValueError("SSE response has no JSON data event")
        parsed = json.loads(text)
        if not isinstance(parsed, dict):
            raise ValueError("HTTP MCP response is not an object")
        return parsed

    def request(
        self,
        payload: dict[str, Any],
        *,
        expect_response: bool = True,
    ) -> dict[str, Any] | None:
        request = urllib.request.Request(
            self.url,
            data=json.dumps(
                payload, ensure_ascii=False, separators=(",", ":")
            ).encode("utf-8"),
            method="POST",
            headers=self._headers(),
        )
        try:
            with urllib.request.urlopen(
                request, timeout=self.timeout
            ) as response:
                session = response.headers.get("Mcp-Session-Id")
                if session:
                    self.session_id = session
                body = response.read()
                if not expect_response or not body.strip():
                    return None
                return self._decode_response(
                    response.headers.get("Content-Type", ""), body
                )
        except urllib.error.HTTPError as error:
            detail = error.read().decode("utf-8", errors="replace")[:2000]
            raise RuntimeError(
                f"HTTP MCP request failed with {error.code}: {detail}"
            ) from error

    def close(self) -> None:
        return None


def _request(
    transport: Any,
    transcript: Transcript,
    request_id: int,
    method: str,
    params: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    response = transport.request({
        "jsonrpc": "2.0",
        "id": request_id,
        "method": method,
        "params": params or {},
    })
    transcript.record(response)
    if not isinstance(response, dict):
        return None
    return response


def _validate_initialize(
    response: dict[str, Any] | None,
    transcript: Transcript,
) -> None:
    def validate() -> None:
        if not isinstance(response, dict):
            raise ValueError("missing initialize response")
        result = response.get("result")
        if not isinstance(result, dict):
            raise ValueError("initialize has no result")
        server = result.get("serverInfo") or {}
        if not isinstance(server.get("name"), str) or not server["name"].strip():
            raise ValueError("serverInfo.name is missing")
        if result.get("protocolVersion") != MCP_PROTOCOL_VERSION:
            raise ValueError(
                "unexpected MCP protocolVersion: "
                f"{result.get('protocolVersion')!r}"
            )
        capabilities = result.get("capabilities") or {}
        if not all(
            name in capabilities
            for name in ("tools", "resources", "prompts")
        ):
            raise ValueError("MCP capabilities must include tools/resources/prompts")

    transcript.attempt("mcp.initialize", validate)


def _valid_tool_output_schema(schema: Any) -> bool:
    if not isinstance(schema, dict) or schema.get("type") != "object":
        return False
    properties = schema.get("properties") or {}
    if isinstance(properties, dict) and "ok" in properties:
        return True
    branches = schema.get("oneOf")
    if not isinstance(branches, list) or len(branches) < 2:
        return False
    success = False
    failure = False
    for branch in branches:
        if not isinstance(branch, dict):
            continue
        branch_properties = branch.get("properties") or {}
        required = set(branch.get("required") or [])
        if (
            isinstance(branch_properties, dict)
            and (branch_properties.get("ok") or {}).get("const") is True
            and {"ok", "data"}.issubset(required)
            and isinstance(branch_properties.get("data"), dict)
        ):
            success = True
        if (
            isinstance(branch_properties, dict)
            and (branch_properties.get("ok") or {}).get("const") is False
            and {"ok", "error"}.issubset(required)
            and isinstance(branch_properties.get("error"), dict)
        ):
            failure = True
    return success and failure


def _typed_output_schema(schema: Any) -> bool:
    if not isinstance(schema, dict):
        return False
    for branch in schema.get("oneOf") or []:
        data = ((branch or {}).get("properties") or {}).get("data")
        if not isinstance(data, dict):
            continue
        if data.get("type") or data.get("oneOf") or data.get("required"):
            return True
    return False


def _validate_profile_playbook(
    resources: Mapping[str, dict[str, Any]],
    tools: set[str],
    profile: str,
    transcript: Transcript,
) -> None:
    def validate() -> None:
        response = resources.get("quant://playbook") or {}
        contents = ((response.get("result") or {}).get("contents") or [])
        text = "\n".join(
            str(item.get("text") or "")
            for item in contents
            if isinstance(item, dict)
        )
        if not text:
            raise ValueError("quant://playbook returned no text")
        referenced = set(re.findall(r"`(quant_[a-z0-9_]+)`", text))
        unknown = sorted(referenced.difference(tools))
        if unknown:
            raise ValueError(
                "playbook references tools outside the active profile: "
                + ", ".join(unknown)
            )
        if profile == "agent":
            forbidden = {
                "quant_capability_install",
                "quant_competition_submit",
                "quant_official_request",
            }.intersection(referenced)
            if forbidden:
                raise ValueError(
                    "default agent playbook references write tools: "
                    + ", ".join(sorted(forbidden))
                )

    transcript.attempt("resources.playbook.profile", validate)


def _validate_tools(
    response: dict[str, Any] | None,
    transcript: Transcript,
    profile: str,
) -> set[str]:
    tools: dict[str, dict[str, Any]] = {}
    required = PROFILE_TOOLS[profile]

    def validate() -> None:
        result = (response or {}).get("result") or {}
        values = result.get("tools")
        if not isinstance(values, list) or not values:
            raise ValueError("tools/list returned no tools")
        for item in values:
            if not isinstance(item, dict) or not isinstance(item.get("name"), str):
                raise ValueError("tool entry is malformed")
            tools[item["name"]] = item
        missing = sorted(required.difference(tools))
        if missing:
            raise ValueError(
                f"{profile} profile tools missing: " + ", ".join(missing)
            )
        for name, item in sorted(tools.items()):
            if not isinstance(item.get("description"), str) or not item[
                "description"
            ].strip():
                raise ValueError(f"{name} has no description")
            schema = item.get("inputSchema")
            if not isinstance(schema, dict) or schema.get("type") != "object":
                raise ValueError(f"{name} inputSchema is not an object schema")
            output_schema = item.get("outputSchema")
            if not _valid_tool_output_schema(output_schema):
                raise ValueError(
                    f"{name} outputSchema is not a structured tool envelope"
                )
            if profile == "agent" and not _typed_output_schema(output_schema):
                raise ValueError(
                    f"{name} has no typed data schema in the default agent profile"
                )
            annotations = item.get("annotations")
            if not isinstance(annotations, dict):
                raise ValueError(f"{name} has no annotations")
            for hint in ("readOnlyHint", "openWorldHint"):
                if not isinstance(annotations.get(hint), bool):
                    raise ValueError(f"{name} lacks boolean {hint}")
        for name in {
            "quant_app_info",
            "quant_agent_handshake",
            "quant_capabilities",
            "quant_capability_list",
            "quant_connector_list",
            "quant_benchmark_list",
            "quant_benchmark_inspect",
        }.intersection(tools):
            if not tools[name]["annotations"]["readOnlyHint"]:
                raise ValueError(f"{name} must be read-only")
        if (
            "quant_connector_pull" in tools
            and not tools["quant_connector_pull"]["annotations"]["openWorldHint"]
        ):
            raise ValueError(
                "quant_connector_pull must declare an open-world side effect risk"
            )
        if "quant_operation_grant_request" in tools:
            for name in (
                "quant_operation_grant_status",
                "quant_operation_grant_list",
            ):
                if not tools[name]["annotations"]["readOnlyHint"]:
                    raise ValueError(f"{name} must be read-only")
            if tools["quant_operation_grant_request"]["annotations"][
                "readOnlyHint"
            ]:
                raise ValueError("quant_operation_grant_request cannot be read-only")
            if "quant_operation_grant_approve" in tools:
                raise ValueError(
                    "operation-grant approval must not be callable by an Agent"
                )
            for name in (
                "quant_capability_install",
                "quant_capability_remove",
                "quant_competition_submit",
                "quant_official_request",
            ):
                if name not in tools:
                    continue
                schema = tools[name].get("inputSchema") or {}
                required_arguments = set(schema.get("required") or [])
                properties = schema.get("properties") or {}
                if (
                    "grantId" not in required_arguments
                    or "confirm" in properties
                ):
                    raise ValueError(
                        f"{name} must require a one-time grant instead of a "
                        "model-supplied confirmation string"
                    )

    transcript.attempt(
        "mcp.tools",
        validate,
    )
    transcript.checks[-1].setdefault("detail", {}).update({
        "required": len(required),
        "profile": profile,
        "observed": len(tools),
        "openWorldObserved": sum(
            1
            for item in tools.values()
            if item.get("annotations", {}).get("openWorldHint") is True
        ),
    })
    return set(tools)


def _validate_next_actions(
    handshake: Mapping[str, Any],
    capabilities: Mapping[str, Any],
) -> None:
    actions = handshake.get("nextActions")
    if not isinstance(actions, list) or not actions:
        raise ValueError("handshake has no nextActions")
    commands = capabilities.get("agent_commands") or capabilities.get("commands")
    contracts = capabilities.get("command_contracts") or {}
    if not isinstance(commands, list) or not isinstance(contracts, dict):
        raise ValueError("capabilities omit callable Agent commands")
    callable_commands = {str(item) for item in commands}
    callable_commands.update(str(item) for item in contracts)
    for index, action in enumerate(actions):
        if not isinstance(action, Mapping):
            raise ValueError(f"nextActions[{index}] is not an object")
        command = str(action.get("command") or "").strip()
        if not command:
            raise ValueError(f"nextActions[{index}] has no command")
        if command not in callable_commands:
            raise ValueError(
                f"nextActions[{index}] is not callable: {command}"
            )


def _validate_resources(
    listing: dict[str, Any] | None,
    reads: dict[str, dict[str, Any] | None],
    transcript: Transcript,
) -> None:
    observed: set[str] = set()

    def validate_listing() -> None:
        result = (listing or {}).get("result") or {}
        values = result.get("resources")
        if not isinstance(values, list) or not values:
            raise ValueError("resources/list returned no resources")
        for item in values:
            if isinstance(item, dict) and isinstance(item.get("uri"), str):
                observed.add(item["uri"])
        missing = sorted(REQUIRED_RESOURCES.difference(observed))
        if missing:
            raise ValueError(
                "required resources missing: " + ", ".join(missing)
            )

    transcript.attempt(
        "mcp.resources",
        validate_listing,
    )
    transcript.checks[-1]["detail"] = {
        "required": len(REQUIRED_RESOURCES),
        "observed": len(observed),
    }

    def validate_read(uri: str) -> None:
        response = reads.get(uri)
        if not response or not isinstance(response.get("result"), dict):
            raise ValueError(f"{uri} read failed")
        _text_resource(response)

    for uri in sorted(REQUIRED_RESOURCES):
        transcript.attempt(
            f"resource.read:{uri}",
            lambda uri=uri: validate_read(uri),
        )

    handshake: dict[str, Any] = {}

    def validate_handshake_resource() -> None:
        value = _json_resource(reads["quant://handshake"] or {})
        if not isinstance(value, dict):
            raise ValueError("handshake resource is not an object")
        handshake.update(value)
        if value.get("format") != "quant-agent-handshake/1":
            raise ValueError("unexpected handshake format")
        protocol = value.get("protocol") or {}
        if protocol.get("name") != PROTOCOL_NAME:
            raise ValueError("unexpected protocol name")
        if str(protocol.get("version")) != PROTOCOL_VERSION:
            raise ValueError("unexpected protocol version")
        if value.get("executionBoundary") != "local":
            raise ValueError("handshake does not declare local execution")
        if protocol.get("semanticConformanceFormat") != SEMANTIC_FORMAT:
            raise ValueError(
                "handshake omits semantic conformance format"
            )
        capabilities = _json_resource(reads["quant://capabilities"] or {})
        _validate_next_actions(value, capabilities)

    transcript.attempt(
        "resource.handshake.semantics",
        validate_handshake_resource,
    )

    def validate_security_resource() -> None:
        value = _json_resource(reads["quant://security"] or {})
        if not isinstance(value, dict):
            raise ValueError("security resource is not an object")
        if value.get("executionBoundary") != "local":
            raise ValueError("security contract is not local")
        invariants = " ".join(
            str(item) for item in value.get("invariants") or []
        )
        for family, needles in REQUIRED_INVARIANTS.items():
            if not _contains_any(invariants, needles):
                raise ValueError(
                    f"security invariants do not cover {family}"
                )

    transcript.attempt(
        "resource.security.semantics",
        validate_security_resource,
    )

    def validate_playbook() -> None:
        text = _text_resource(reads["quant://playbook"] or {})
        required = (
            "factor",
            "backtest",
            "evidence",
            "local",
            "submission",
            "credentials",
        )
        lower = text.lower()
        missing = [item for item in required if item not in lower]
        if missing:
            raise ValueError(
                "playbook omits core protocol concepts: "
                + ", ".join(missing)
            )
        if "quant_agent_handshake" not in text:
            raise ValueError("playbook omits handshake bootstrap")

    transcript.attempt("resource.playbook.semantics", validate_playbook)

    def validate_capabilities() -> None:
        value = _json_resource(reads["quant://capabilities"] or {})
        if not isinstance(value, dict):
            raise ValueError("capabilities resource is not an object")
        commands = value.get("commands")
        if not isinstance(commands, list) or not commands:
            raise ValueError("capabilities resource has no commands")
        if "mcp.serve" not in commands:
            raise ValueError("capabilities omit mcp.serve")

    transcript.attempt(
        "resource.capabilities.semantics",
        validate_capabilities,
    )

    def validate_operators() -> None:
        value = _json_resource(reads["quant://operators"] or {})
        operators = value.get("operators") if isinstance(value, dict) else None
        if not isinstance(operators, list) or len(operators) < 1:
            raise ValueError("operator resource is empty")

    transcript.attempt("resource.operators.semantics", validate_operators)


def _validate_prompts(
    listing: dict[str, Any] | None,
    prompt: dict[str, Any] | None,
    transcript: Transcript,
) -> None:
    observed: set[str] = set()

    def validate_listing() -> None:
        result = (listing or {}).get("result") or {}
        values = result.get("prompts")
        if not isinstance(values, list) or not values:
            raise ValueError("prompts/list returned no prompts")
        for item in values:
            if isinstance(item, dict) and isinstance(item.get("name"), str):
                observed.add(item["name"])
        missing = sorted(REQUIRED_PROMPTS.difference(observed))
        if missing:
            raise ValueError("required prompts missing: " + ", ".join(missing))

    transcript.attempt(
        "mcp.prompts",
        validate_listing,
    )
    transcript.checks[-1]["detail"] = {
        "required": len(REQUIRED_PROMPTS),
        "observed": len(observed),
    }

    def validate_prompt() -> None:
        result = (prompt or {}).get("result") or {}
        messages = result.get("messages")
        if not isinstance(messages, list) or not messages:
            raise ValueError("prompts/get returned no messages")
        content = messages[0].get("content") or {}
        text = content.get("text")
        if not isinstance(text, str) or "local" not in text.lower():
            raise ValueError("research prompt does not preserve local boundary")

    transcript.attempt("prompt.quant_research.semantics", validate_prompt)


def _validate_tool_calls(
    handshake_call: dict[str, Any] | None,
    capabilities_call: dict[str, Any] | None,
    app_info_call: dict[str, Any] | None,
    transcript: Transcript,
) -> None:
    data: dict[str, Any] = {}

    def validate_handshake() -> None:
        envelope = _parse_structured(handshake_call or {})
        if not envelope["ok"]:
            raise ValueError("handshake tool returned ok=false")
        value = envelope.get("data") or {}
        if not isinstance(value, dict):
            raise ValueError("handshake data is not an object")
        data.update(value)
        if value.get("format") != "quant-agent-handshake/1":
            raise ValueError("unexpected handshake tool format")
        protocol = value.get("protocol") or {}
        if protocol.get("name") != PROTOCOL_NAME:
            raise ValueError("handshake tool reports another protocol")
        if str(protocol.get("version")) != PROTOCOL_VERSION:
            raise ValueError("handshake tool reports another version")
        if value.get("executionBoundary") != "local":
            raise ValueError("handshake tool is not local")
        if protocol.get("semanticConformanceFormat") != SEMANTIC_FORMAT:
            raise ValueError(
                "handshake tool omits semantic conformance format"
            )
        security = value.get("security") or {}
        required_security = {
            "executionBoundary": "local",
            "privateByDefault": True,
            "factorRunDoesNotSubmitOrPublish": True,
            "sourceUploadRequiresExplicitRequest": True,
            "marketDataUploadRequiresExplicitRequest": True,
        }
        for key, expected in required_security.items():
            if security.get(key) != expected:
                raise ValueError(f"handshake security {key} is not {expected!r}")
        resources = set(protocol.get("resourceUris") or [])
        missing = REQUIRED_RESOURCES.difference(resources)
        if missing:
            raise ValueError(
                "handshake omits resources: " + ", ".join(sorted(missing))
            )
        capabilities = _parse_structured(capabilities_call or {}).get("data") or {}
        _validate_next_actions(value, capabilities)

    transcript.attempt("tool.handshake.semantics", validate_handshake)

    def validate_capabilities() -> None:
        envelope = _parse_structured(capabilities_call or {})
        if not envelope["ok"]:
            raise ValueError("capabilities tool returned ok=false")
        value = envelope.get("data") or {}
        commands = value.get("commands") if isinstance(value, dict) else None
        if not isinstance(commands, list) or "mcp.serve" not in commands:
            raise ValueError("tool capabilities omit mcp.serve")

    transcript.attempt(
        "tool.capabilities.semantics",
        validate_capabilities,
    )

    def validate_app_info() -> None:
        envelope = _parse_structured(app_info_call or {})
        value = envelope.get("data") or {}
        if not isinstance(value, dict):
            raise ValueError("app.info data is not an object")
        agent = value.get("agent")
        if not isinstance(agent, dict):
            raise ValueError("app.info omits agent discovery")
        if agent.get("protocolName") != PROTOCOL_NAME:
            raise ValueError("app.info reports another protocol")
        if not str(agent.get("protocolVersion")) == PROTOCOL_VERSION:
            raise ValueError("app.info reports another protocol version")
        if agent.get("clientProductCode") != "quant-research-client":
            raise ValueError("app.info conflates protocol/client with another product")
        if agent.get("competitionProductCode") != "quant-arena":
            raise ValueError("app.info does not separate the competition product")

    transcript.attempt("tool.app_info.semantics", validate_app_info)


def _declared_tool_profile(handshake_call: dict[str, Any] | None) -> str:
    envelope = _parse_structured(handshake_call or {})
    if not envelope["ok"]:
        raise ValueError("handshake tool returned ok=false")
    value = envelope.get("data") or {}
    protocol = value.get("protocol") or {}
    profile = str(protocol.get("toolSurfaceProfile") or "core").strip().lower()
    if profile not in PROFILE_TOOLS:
        raise ValueError(f"unknown tool surface profile: {profile}")
    return profile


def _validate_tool_surface_profile(
    profile: str,
    observed_tools: set[str],
    transcript: Transcript,
) -> str:
    def validate() -> None:
        required = PROFILE_TOOLS[profile]
        missing = sorted(required.difference(observed_tools))
        if missing:
            raise ValueError(
                f"{profile} tool surface is incomplete: "
                + ", ".join(missing)
            )

    transcript.attempt("mcp.tool_surface_profile", validate)
    transcript.checks[-1].setdefault("detail", {}).update({
        "profile": profile,
        "required": len(PROFILE_TOOLS[profile]),
        "observed": len(observed_tools),
    })
    return profile


def _secret_leaks(transcript: Transcript) -> list[str]:
    payload = json.dumps(
        transcript.responses,
        ensure_ascii=False,
        sort_keys=True,
    )
    leaks = []
    for name, value in os.environ.items():
        upper = name.upper()
        if not any(
            marker in upper
            for marker in ("TOKEN", "PASSWORD", "SECRET", "API_KEY", "APIKEY")
        ):
            continue
        secret = str(value)
        if len(secret) >= 8 and secret in payload:
            leaks.append(name)
    return sorted(leaks)


def _generated_at() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds").replace(
        "+00:00",
        "Z",
    )


def _looks_like_absolute_path(value: str) -> bool:
    text = str(value)
    return (
        text.startswith("/")
        or text.startswith("\\\\")
        or (
            len(text) >= 3
            and text[0].isalpha()
            and text[1] == ":"
            and text[2] in {"\\", "/"}
        )
    )


def _display_target(command: str | None, args: Sequence[str]) -> str:
    if not command:
        return ""
    name = command.replace("\\", "/").rstrip("/").rsplit("/", 1)[-1]
    rendered = [
        "<local-path>" if _looks_like_absolute_path(str(item)) else str(item)
        for item in args
    ]
    return " ".join([name, *rendered]).strip()


def _target_artifact(args: Sequence[str]) -> dict[str, Any] | None:
    for item in args:
        text = str(item)
        if text.startswith("-"):
            continue
        path = Path(text).expanduser()
        if (
            path.is_file()
            and path.suffix.lower() in {".py", ".js", ".cjs", ".mjs"}
        ):
            content = path.read_bytes()
            return {
                "kind": path.suffix.lower().lstrip("."),
                "bytes": len(content),
                "sha256": hashlib.sha256(content).hexdigest(),
            }
    return None


def _verifier_identity() -> dict[str, Any]:
    path = Path(__file__).resolve()
    data = path.read_bytes()
    return {
        "version": VERIFIER_VERSION,
        "bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
        "profileManifestSha256": _sha256(_canonical_json(PROFILE_MANIFEST)),
    }


def _runtime_summary(
    handshake_call: dict[str, Any] | None,
    app_info_call: dict[str, Any] | None,
    profile: str,
) -> dict[str, Any]:
    handshake = _parse_structured(handshake_call or {}).get("data") or {}
    app_info = _parse_structured(app_info_call or {}).get("data") or {}
    client = handshake.get("client") if isinstance(handshake, dict) else {}
    state = handshake.get("state") if isinstance(handshake, dict) else {}
    runtime = state.get("runtime") if isinstance(state, dict) else {}
    data = state.get("data") if isinstance(state, dict) else {}
    return {
        "clientVersion": (
            client.get("version")
            if isinstance(client, dict)
            else None
        )
        or (
            app_info.get("agent", {}).get("clientVersion")
            if isinstance(app_info, dict)
            else None
        )
        or (
            app_info.get("clientVersion")
            if isinstance(app_info, dict)
            else None
        ),
        "runtimeVersion": (
            runtime.get("version")
            if isinstance(runtime, dict)
            else None
        ),
        "dataPackageVersion": (
            data.get("packageVersion")
            if isinstance(data, dict)
            else None
        ),
        "runtimeReady": (
            runtime.get("ready")
            if isinstance(runtime, dict)
            else None
        ),
        "toolkitVersions": (
            runtime.get("storage", {}).get("toolkitVersions")
            if isinstance(runtime, dict)
            and isinstance(runtime.get("storage"), dict)
            else None
        ),
        "executionBoundary": handshake.get("executionBoundary"),
        "toolSurfaceProfile": profile,
    }


def verify(
    *,
    command: str | None = None,
    args: Sequence[str] = (),
    cwd: str | Path | None = None,
    url: str | None = None,
    token: str = "",
    timeout: float = 60.0,
    semantic: bool = False,
) -> dict[str, Any]:
    """Run the read-only conformance suite and return an evidence report."""
    transport: Any
    artifact = None
    if command:
        transport = StdioTransport(
            command,
            args,
            cwd=cwd,
            timeout=timeout,
        )
        target = _display_target(command, args)
        artifact = _target_artifact(args)
        transcript = Transcript(transport="stdio", target=target)
    elif url:
        if not str(token).strip():
            raise ValueError("HTTP conformance requires a bearer token")
        transport = HttpTransport(str(url), token=str(token), timeout=timeout)
        transcript = Transcript(transport="streamable-http", target=str(url))
    else:
        raise ValueError("provide a stdio command or an HTTP MCP URL")

    semantic_report = None
    tool_surface_profile = "unknown"
    try:
        initialize = _request(
            transport,
            transcript,
            1,
            "initialize",
            {
                "protocolVersion": MCP_PROTOCOL_VERSION,
                "capabilities": {},
                "clientInfo": {
                    "name": "qprotocol-verify",
                    "version": CONFORMANCE_FORMAT,
                },
            },
        )
        _validate_initialize(initialize, transcript)

        transport.request(
            {
                "jsonrpc": "2.0",
                "method": "notifications/initialized",
                "params": {},
            },
            expect_response=False,
        )

        handshake_call = _request(
            transport,
            transcript,
            2,
            "tools/call",
            {"name": "quant_agent_handshake", "arguments": {}},
        )
        declared_profile = _declared_tool_profile(handshake_call)

        tools_listing = _request(
            transport, transcript, 3, "tools/list", {}
        )
        observed_tools = _validate_tools(
            tools_listing, transcript, declared_profile,
        )

        resources_listing = _request(
            transport, transcript, 4, "resources/list", {}
        )
        resources_read = {
            uri: _request(
                transport,
                transcript,
                10 + index,
                "resources/read",
                {"uri": uri},
            )
            for index, uri in enumerate(sorted(REQUIRED_RESOURCES))
        }
        _validate_resources(resources_listing, resources_read, transcript)
        _validate_profile_playbook(
            resources_read,
            observed_tools,
            declared_profile,
            transcript,
        )

        prompts_listing = _request(
            transport, transcript, 5, "prompts/list", {}
        )
        prompt = _request(
            transport,
            transcript,
            6,
            "prompts/get",
            {
                "name": "quant_research",
                "arguments": {
                    "goal": "Verify read-only protocol conformance."
                },
            },
        )
        _validate_prompts(prompts_listing, prompt, transcript)

        capabilities_call = _request(
            transport,
            transcript,
            7,
            "tools/call",
            {"name": "quant_capabilities", "arguments": {}},
        )
        app_info_call = _request(
            transport,
            transcript,
            8,
            "tools/call",
            {"name": "quant_app_info", "arguments": {}},
        )
        _validate_tool_calls(
            handshake_call,
            capabilities_call,
            app_info_call,
            transcript,
        )
        tool_surface_profile = _validate_tool_surface_profile(
            declared_profile,
            observed_tools,
            transcript,
        )

        if semantic:
            semantic_report = _run_semantic_vectors(
                transport,
                transcript,
                request_id=20,
                timeout=timeout,
            )

        leaks = _secret_leaks(transcript)
        transcript.check(
            "security.no_credential_values",
            not leaks,
            detail={"leakedEnvironmentNames": leaks},
        )
    finally:
        transport.close()

    failed = [item for item in transcript.checks if not item["passed"]]
    transcript_sha = _sha256(_canonical_json(transcript.responses))
    observed_tool_entries = (
        ((tools_listing or {}).get("result") or {}).get("tools") or []
    )
    typed_output_schemas = sum(
        1
        for item in observed_tool_entries
        if isinstance(item, dict)
        and _typed_output_schema(item.get("outputSchema"))
    )
    return {
        "format": CONFORMANCE_FORMAT,
        "reportVersion": 1,
        "generatedAt": _generated_at(),
        "status": "CONFORMING" if not failed else "NON_CONFORMING",
        "conforming": not failed,
        "protocol": {
            "name": PROTOCOL_NAME,
            "version": PROTOCOL_VERSION,
            "mcpProtocol": MCP_PROTOCOL_VERSION,
        },
        "transport": transcript.transport,
        "target": transcript.target,
        "targetArtifact": artifact,
        "verifier": _verifier_identity(),
        "runtime": _runtime_summary(
            handshake_call,
            app_info_call,
            tool_surface_profile,
        ),
        "summary": {
            "checks": len(transcript.checks),
            "passed": len(transcript.checks) - len(failed),
            "failed": len(failed),
            "toolsObserved": len(observed_tools),
            "typedOutputSchemas": typed_output_schemas,
            "resourcesRequired": len(REQUIRED_RESOURCES),
            "promptsRequired": len(REQUIRED_PROMPTS),
            "toolSurfaceProfile": tool_surface_profile,
        },
        "semanticConformance": semantic_report,
        "checks": transcript.checks,
        "errors": [
            {
                "id": item["id"],
                "detail": item.get("detail"),
            }
            for item in failed
        ],
        "transcriptSha256": transcript_sha,
        "mutatedResearchState": False,
        "uploadedLocalContent": False,
        "executedFactors": False,
        "executedSyntheticVectors": bool(
            semantic_report
            and semantic_report.get("executedSyntheticVectors")
        ),
        "note": (
            "This report checks the observable MCP contract. It is not a "
            "security audit, investment endorsement, or proof of correct "
            "factor performance."
        ),
    }


def _write_report(path: str | Path, report: dict[str, Any]) -> Path:
    target = Path(path).expanduser().resolve()
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(
        json.dumps(
            report,
            ensure_ascii=False,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )
        + "\n",
        encoding="utf-8",
    )
    return target


def main(argv: Sequence[str] | None = None) -> int:
    raw_args = list(sys.argv[1:] if argv is None else argv)
    normalized: list[str] = []
    index = 0
    while index < len(raw_args):
        if raw_args[index] == "--arg" and index + 1 < len(raw_args):
            normalized.append("--arg=" + raw_args[index + 1])
            index += 2
            continue
        normalized.append(raw_args[index])
        index += 1
    parser = argparse.ArgumentParser(
        description="Verify a Quant Research Protocol MCP runtime",
    )
    source = parser.add_mutually_exclusive_group(required=True)
    source.add_argument("--command")
    source.add_argument("--url")
    parser.add_argument(
        "--arg",
        action="append",
        default=[],
        help="Argument passed verbatim to --command; repeat as needed.",
    )
    parser.add_argument("--cwd")
    parser.add_argument(
        "--token",
        default="",
        help="Bearer token for --url. Prefer --token-env.",
    )
    parser.add_argument(
        "--token-env",
        default="QUANT_AGENT_TOKEN",
        help="Read the HTTP bearer token from this environment variable.",
    )
    parser.add_argument("--timeout", type=float, default=60.0)
    parser.add_argument(
        "--semantic",
        action="store_true",
        help=(
            "Execute a temporary synthetic Alpha Graph vector after structural "
            "checks; user data and research state are not accessed."
        ),
    )
    parser.add_argument("--output")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args(normalized)
    if args.url:
        token = str(args.token or os.environ.get(args.token_env, "")).strip()
    else:
        token = ""
    if args.command and args.arg and not args.command:
        parser.error("--arg requires --command")
    try:
        report = verify(
            command=args.command,
            args=args.arg,
            cwd=args.cwd,
            url=args.url,
            token=token,
            timeout=args.timeout,
            semantic=args.semantic,
        )
    except Exception as error:  # noqa: BLE001 - standalone diagnostic
        report = {
            "format": CONFORMANCE_FORMAT,
            "reportVersion": 1,
            "generatedAt": _generated_at(),
            "status": "ERROR",
            "conforming": False,
            "protocol": {
                "name": PROTOCOL_NAME,
                "version": PROTOCOL_VERSION,
                "mcpProtocol": MCP_PROTOCOL_VERSION,
            },
            "errors": [
                {
                    "id": "verifier.execution",
                    "detail": f"{type(error).__name__}: {error}",
                }
            ],
            "verifier": _verifier_identity(),
            "mutatedResearchState": False,
            "uploadedLocalContent": False,
            "executedFactors": False,
            "executedSyntheticVectors": False,
        }
    if args.output:
        report["report"] = str(_write_report(args.output, report))
    if args.json:
        print(json.dumps(report, ensure_ascii=False, sort_keys=True))
    else:
        print(f"Quant Research Protocol: {report['status']}")
        summary = report.get("summary") or {}
        print(
            "Checks: "
            f"{summary.get('passed', 0)} passed / "
            f"{summary.get('checks', 0)} total"
        )
        for error in report.get("errors") or []:
            print(f"ERROR {error.get('id')}: {error.get('detail')}")
        if args.semantic:
            semantic_report = report.get("semanticConformance") or {}
            print(
                "Semantic Alpha Graph: "
                f"{semantic_report.get('status', 'ERROR')}"
            )
        print(f"Transcript SHA-256: {report.get('transcriptSha256') or '<unavailable>'}")
    return 0 if report.get("conforming") else 1


if __name__ == "__main__":
    raise SystemExit(main())
